INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('No shoes in Boots and Curry’s is not a takeaway – Kerry organisations help Ukrainians to settle in', 'no-shoes-in-boots-and-currys-is-not-a-takeaway-kerry-organisations-help-ukrainians-to-settle-in', '<p>A Co Kerry local development company has launched an online professional recognition guide to help Ukrainian refugees reconnect with their career choices. It will help people from career backgrounds as varied as law to hairdressing.</p>
<p>The online resource consists of advice in PDF and other formats, all accessible on Google Drive.</p>
<p>It gives Ukrainians information regarding how their qualifications are viewed by professional bodies in Ireland and what, if anything, they need to do to have their qualifications recognised in Ireland.</p>
<p>The guide was developed by Ukrainian support workers of North East West Kerry Development (NEWKD) in partnership with Kerry County Community Response Forum.</p>
<p>The guide applies only to those who received temporary protection under the EU Temporary Protection Directive. It has been shared with the Ukraine Civil Society Response Forum Ireland and with the Irish Local Development Network.</p>
<p>The resource has been accessed thousands of times. NEWKD’s folder of resources on Google Drive is available<a href="https://drive.google.com/drive/folders/1bwoaMesa7Cm-IX7kowbyF8N6T5C3cJCr"> here.</a></p>
<p><img fetchpriority="high" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/07/Screenshot-4.png" alt="" width="1023" height="678" srcset="https://changingireland.ie/wp-content/uploads/2024/07/Screenshot-4.png 1023w, https://changingireland.ie/wp-content/uploads/2024/07/Screenshot-4-300x199.png 300w, https://changingireland.ie/wp-content/uploads/2024/07/Screenshot-4-768x509.png 768w" sizes="(max-width: 1023px) 100vw, 1023px" /></p>
<p>A one-stop-shop website for Ukrainians in Kerry explaining everything you need to know about Ireland has become so popular nationally that development workers are calling for it to be resourced long-term.</p>
<p>Many Ukrainians on first arrival here head to Boots, because they expect they’ll need good footwear for wintertime like at home. They are perplexed to find that Boots here is a pharmacy. They cannot rely on Google Translate.</p>
<p>Similarly, Ukrainians who want to buy an electronic device are puzzled when Google directs them towards Curry&#8217;s which they know as an Indian dish.</p>
<p>Rules around public services, from employment schemes to information on education, can also be confusing for people.</p>
<p>The website <a href="https://ukrainiansinkerry.ie/">www.ukrainiansinkerry.ie</a> links directly to government, public service and commercial websites of use to newcomers.</p>
<p>As well as helping Ukrainians, the site also reduced repeat queries to staff and released them to do more development work.</p>
<p>While the development worker who led this project is securely employed through the Social Inclusion and Community Activation Programme, funding for two team-mates has run out.</p>
<p>Olya Marynetseva from North East West Kerry Development says the website could be easily replicated in other counties. For more information, or to offer collaborative support, call Olya at 066 7180190, or email OlyaMaryntseva@newkd.ie.</p>
<p>Not all resources for Ukrainians in Co Kerry are online &#8211; Tralee Library now has a special bookshelf with links to libraries around the world.</p>
<p>The Ukrainian bookshelf is part of a global project by Ukraine&#8217;s First Lady, Olena Zelenska, which has seen 44,000 books displayed on 170 shelves in 37 countries and counting.</p>
<p>The Ukrainian Bookshelf in Kerry was officially launched by the Ambassador of Ukraine to Ireland, Larysa Gerasko, and the then Mayor of Kerry County Council Jim Finucane.</p>
<p>The idea is spreading within Ireland, with Ukrainian bookshelves in libraries in Dublin, Limerick and elsewhere.</p>
<p>&nbsp;</p>
<p>&nbsp;</p>', 'Ukrainian support workers in North East West Kerry Development (NEWKD) have created online resources for Ukrainian refugees about life in Ireland and information on career options. Tralee Library has also installed a Ukrainian language bookshelf.', 'https://changingireland.ie/wp-content/uploads/2024/07/The-Ukrainian-Bookshelf-in-Kerry-was-officially-launched-by-the-Ambassador-of-Ukraine-to-Ireland-Larysa-Gerasko-and-then-Mayor-of-Kerry-County-Council-Jim-Finucane.jpeg', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[{"slug":"community-development","title":"community development"},{"slug":"education","title":"education"},{"slug":"kerry","title":"Kerry"},{"slug":"local-development-company","title":"local development company"},{"slug":"north-east-and-west-kerry-development-newkd","title":"North East and West Kerry Development NEWKD"},{"slug":"refugee-support","title":"Refugee support"},{"slug":"refugees","title":"refugees"},{"slug":"tralee","title":"Tralee"},{"slug":"ukraine","title":"Ukraine"},{"slug":"ukrainian-refugees","title":"Ukrainian refugees"},{"slug":"ukrainian-support-workers","title":"ukrainian support workers"}]', '', 254373, 1, '2024-07-31T11:03:26Z', '2024-07-31T11:24:28Z', '2024-07-31T11:03:26Z')
