INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Protests leading to boycott on Israeli firms', 'protests-leading-to-boycott-on-israeli-firms', '<p>At TCD, a five-day encampment by student campaigners ended on May 8 after the students secured agreement from the university management to desist from investing in Israeli projects.</p>
<p>A statement by the university said: “We fully understand the driving force behind the encampment on our campus and we are in solidarity with the students.”</p>
<p>TCD agreed to a number of requests by the protestors, including a divestment from “investments in Israeli companies that have activities in the Occupied Palestinian Territory and appear on the UN Blacklist in this regard”. It also pledged to “endeavour to divest from investments in other Israeli companies”. The statement also said TCD would give fully funded places to six postgraduate and two undergraduate scholars from Gaza.</p>
<p>The encampment at UCD ended on June 8 following successful talks between university management and protestors.</p>
<p>“We are outraged by the ongoing mass killing of civilians, the withholding of humanitarian aid, and the destruction in Palestine by Israel. As a member of the global university community with an enduring commitment to academic freedom, expression and safety, UCD is particularly appalled by the destruction of all universities in Gaza and attacks on their students, faculty and staff,” said a statement from the university.<br />
UCD pledged to introduce a number of the requested measures, including the establishment of up to eight sanctuary scholarships for displaced Palestinian applicants.</p>
<p>It will also create a working group, including nominees of the UCD Students’ Union, “to develop a policy on ethical investment by June 2025 for approval by Governing Authority”.</p>', 'Successful student protests nationwide targeted universities’ Israeli investments. Some of the most high-profile protests include the student encampments at Trinity College Dublin (TCD), University College Dublin (UCD) and University College Cork (UCC).', 'https://changingireland.ie/wp-content/uploads/2024/07/UCD-1.jpg', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"}]', '[]', '', 254300, 1, '2024-07-26T11:03:39Z', '2024-07-26T11:03:43Z', '2024-07-26T11:03:39Z')
