INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New online tool aims to improve access to mental health supports', 'new-online-tool-aims-to-improve-access-to-mental-health-supports', '<p><span>The new resource aims to bridge the gap in mental health support and ensure that young people can find the help they need quickly and efficiently. </span></p>
<p><span>The search engine allows users to simply select the issue affecting their mental health, or the mental health of the young person they are supporting, and the area in which they live, to find appropriate support services.</span></p>
<p><span>It contains information and contact details for supports for a range of issues including substance use, eating disorders and self harm.</span></p>
<p><span>It also highlights supports available for LGBT+ young people, migrant communities, and neurodivergent young people, among many others. </span></p>
<p><span>Minister of State for Mental Health and Older People Mary Butler said the development “marks a significant step forward in how we continue to support youth mental health in innovative ways”. </span></p>
<p><span>“Young people have embraced modern technology and receive a lot of their information from their phones and devices. It is crucial that young people have access to the right, appropriate supports when they need them, in an age of misinformation and disinformation. This signposting tool will play a vital role to ensure access to the many supports for youth mental health are highlighted and signposted and will also support their families,&#8221; she added</span></p>
<p><span>NYCI national youth health programme manager Rachael Traenor said the tool “showcases the wealth of good work already being carried out by youth workers and youth services to support young people&#8217;s mental health”. </span></p>
<p><span>She continued: “We are immensely proud of the collaborative work that has gone into developing this tool. It reflects our commitment to enhancing youth mental health support across Ireland. Our thanks go to all the organisations and individuals who have contributed to this important initiative.&#8221; </span></p>
<p>Click <a href="https://www.youth.ie/programmes/youth-health/youth-mental-health-signposting-tool/">here</a> to access the new Online Youth Mental Health Signposting Tool.</p>', 'The National Youth Council of Ireland (NYCI) has launched a new Online Youth Mental Health Signposting Tool, which is designed to provide young people, parents and youth workers easy access to mental health resources and services locally.', 'https://changingireland.ie/wp-content/uploads/2024/07/40Sa8K7j.jpeg', '', '[{"slug":"empowerment","title":"Empowerment"}]', '[{"slug":"eating-disorders","title":"eating disorders"},{"slug":"lgbt","title":"LGBT"},{"slug":"mental-health","title":"mental health"},{"slug":"mental-health-support-services","title":"mental health support services"},{"slug":"migrant-community","title":"migrant community"},{"slug":"minister-mary-butler","title":"Minister Mary Butler"},{"slug":"national-youth-council-of-ireland-nyci","title":"National Youth Council of Ireland (NYCI)"},{"slug":"neurodivergent","title":"neurodivergent"},{"slug":"self-harm","title":"self harm"},{"slug":"substance-use","title":"substance use"},{"slug":"youth-work","title":"youth work"}]', '', 254277, 1, '2024-07-15T11:47:38Z', '2024-07-15T11:52:31Z', '2024-07-15T11:47:38Z')
