INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€1 million funding to create 42 new Community Services Programme positions', 'e1-million-funding-to-create-42-new-community-services-programme-positions', '<p><span>Minister of State at the Department of Rural and Community Development, Joe O&#8217;Brien has announced funding for 42 additional positions under the Community Services Programme (CSP).</span></p>
<p><span>A total of 32</span><span> organisations across Ireland are set to benefit from the investment, which will see approximately €1 million in additional funding allocated to the programme.</span></p>
<p><span>The CSP supports community-based organisations to provide local social, economic and environmental services through a social enterprise model.</span></p>
<p><span>It aims to tackle disadvantage by providing a co-funding contribution towards the cost of employing a manager and full-time equivalent (FTE) positions.</span></p>
<p><span>This announcement follows a call for additional funding requests to existing CSP services, which took place in September 2023.</span></p>
<p><span>The investment will result in an extra seven managers and 35 full time equivalent (FTE) positions being supported.</span></p>
<p><span>Minister O&#8217;Brien commented: &#8220;I am delighted to announce these additional posts for the Community Services Programme, and to extend the capacity of our CSP organisations to deliver vital services in our communities.&#8221;</span></p>
<p><span>&#8220;The organisations supported under the Community Services Programme provide a wealth of services to meet the needs of their communities, while also providing local employment and contributing to sustainable, inclusive and empowered communities. I am committed to continuing to support these organisations and am delighted to announce the funding for these additional posts.&#8221; </span></p>
<p><span>The Community Services Programme has evolved over recent years, and in line with emerging priorities, a new needs-based differential funding model was introduced from January 2023.</span></p>
<p><span>An increase in the funding contributions to CSP organisations was announced in December 2023, to help CSP organisations to implement the increased national minimum wage for all staff. </span></p>
<p><span>The CSP contribution supports organisations to meet local service gaps and provide access to services and facilities that would potentially otherwise be unavailable.</span></p>
<p><span>There are currently 449 community based services supported by the CSP through 429 organisations throughout the country.</span></p>
<p><span>The full list of organisations can be found </span><a href="https://www.gov.ie/pdf/?file=https://assets.gov.ie/296363/6b9f4934-6feb-48bf-bf52-362f4c1b4a15.pdf"><span>here</span></a></p>
<p>&nbsp;</p>', '32 organisations are set to benefit from fresh investment in the programme, which aims to tackle disadvantage through a social enterprise model.', 'https://changingireland.ie/wp-content/uploads/2022/08/Minister-Joe-OBrien-e1718881622408.jpg', '', '[{"slug":"initiatives","title":"Initiatives"}]', '[{"slug":"community-and-voluntary-sector","title":"Community and Voluntary sector"},{"slug":"community-employment","title":"Community Employment"},{"slug":"community-organisations","title":"Community organisations"},{"slug":"community-services-programme-csp","title":"Community Services Programme CSP"},{"slug":"community-work","title":"community work"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"employment","title":"employment"},{"slug":"employment-schemes","title":"employment schemes"},{"slug":"funding","title":"funding"},{"slug":"inclusion","title":"Inclusion"},{"slug":"minister-joe-obrien","title":"Minister Joe O''Brien"},{"slug":"social-enterprise","title":"social enterprise"}]', '', 254255, 1, '2024-06-19T09:07:35Z', '2024-06-20T11:08:19Z', '2024-06-19T09:07:35Z')
