INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('“Deliberate” delays with regeneration are breaking up Dolphin House community', 'deliberate-delays-with-regeneration-are-breaking-up-dolphin-house-community', '<p><span>They want a dedicated senior manager appointed with powers to move regeneration forward, and they made this point forcefully </span><span>today at a press </span><span>briefing held in the area.</span></p>
<p><span>The community leaders are desperate to break the logjam, and they have written to the Irish Human Rights and Equality </span><span>Commission complaining about repeated and</span> “deliberate” delays by the State and Dublin City Council.</p>
<p><span>The flats were built in 1957 and are now in very poor condition. When residents move out or pass away the windows and doors </span><span>are shuttered, which breaks the strong sense of community that has prevailed for decades.</span></p>
<p><span>It is a neighbourly and proud working class community that battles against disadvantage, say community leaders. Generations of </span><span>families live together, providing vital support to each other.</span></p>
<p><span>However, community leaders today warned: </span><span>“Housing conditions in the unregenerated estate include mould, damp, overcrowding and anti-social behaviour. The community </span><span>is in danger of crumbling under the weight of this neglect. Ill health and mental health challenges are a feature of daily life.”</span></p>
<p><span>&#8220;Dolphin House and Park sits on 18.5 acres and comprises of 436 homes, made up of 392 flats in six blocks. It was promised a full </span><span>regeneration over 20 years ago, but only a quarter was completed, leaving the majority in squalid conditions.”</span></p>
<figure aria-describedby="caption-attachment-254243"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-scaled.jpg" alt="" width="2560" height="1707" srcset="https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-scaled.jpg 2560w, https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2024/06/This-was-once-a-football-pitch-until-half-of-it-was-taken-for-development-and-the-remainder-let-turn-into-waste-ground-1080x720.jpg 1080w" sizes="(max-width: 2560px) 100vw, 2560px" /><figcaption>&#8211; This was once a football pitch, until half of it was taken for development and the remainder let turn into waste ground</figcaption></figure>
<h3><strong>STATEMENT</strong></h3>
<p><span>Fergus Finlay and Una Lowry said: “For more than three years there has been an agreed masterplan to complete the </span><span>regeneration.&#8221;</span></p>
<p><span>They added that the plan would provide more than 700 high quality social housing units &#8220;in the midst of an overwhelming housing </span><span>crisis&#8221;.</span></p>
<p><span>Fergus, the well-known former head of Barnardos, is chair of Dolphin House Regeneration Board. Una, who serves as CEO of </span><span>Dublin South City Partnership, is chair of Dolphin House Community Development Association.</span></p>
<p><span>In the wider area, they and others have identified other regeneration projects “all stuck in similar ways to us” that between them </span><span>could contribute 2,500 new high quality social housing units.</span></p>
<p><span>“We have met the Minister for Housing who has told us that he finds these timelines indefensible. A Cabinet sub-committee </span><span>meeting on December 16 last issued an instruction that the timelines were to be shortened.</span></p>
<p><span>“Every government minister and public representative to whom we have spoken has assured us that money is not the problem. </span><span>Not a single one of them has said that the lack of progress is appropriate or defensible.</span></p>
<p><span>“Yet nothing has happened and conditions in the estate continue to deteriorate. Many longstanding families have given up hope in </span><span>the regeneration process and are seeking to leave – we are witnessing the breakup of a community.</span></p>
<p><span>“On behalf of the community in Dolphin House we are today launching a Human Rights campaign against the broken promises </span><span>of the State and Dublin City Council in regard to the regeneration of Dolphin.</span></p>
<p><span>“As a first step we have written to the Irish Human Rights and Equality Commission, asking them to initiate an enquiry under </span><span>Section 35 of the Human Rights Act,” they revealed.</span></p>
<p><span>The Act provides for such an enquiry in a situation where there is a serious violation of human rights or equality of treatment </span><span>obligations in respect of any group of citizens, or a systemic failure to comply with human rights.</span></p>
<p><span>“We have sought advice to be sure that that situation applies here,” added the community spokespeople.</span></p>
<figure aria-describedby="caption-attachment-254246"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/06/Photo-courtesy-of-Dolphin-House-Community-Centre-from-earlier-this-year.jpg" alt="" width="1225" height="919" srcset="https://changingireland.ie/wp-content/uploads/2024/06/Photo-courtesy-of-Dolphin-House-Community-Centre-from-earlier-this-year.jpg 1225w, https://changingireland.ie/wp-content/uploads/2024/06/Photo-courtesy-of-Dolphin-House-Community-Centre-from-earlier-this-year-300x225.jpg 300w, https://changingireland.ie/wp-content/uploads/2024/06/Photo-courtesy-of-Dolphin-House-Community-Centre-from-earlier-this-year-1024x768.jpg 1024w, https://changingireland.ie/wp-content/uploads/2024/06/Photo-courtesy-of-Dolphin-House-Community-Centre-from-earlier-this-year-768x576.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/06/Photo-courtesy-of-Dolphin-House-Community-Centre-from-earlier-this-year-1080x810.jpg 1080w" sizes="(max-width: 1225px) 100vw, 1225px" /><figcaption>• Photo courtesy of Dolphin House Community Centre from earlier this year.</figcaption></figure>', 'Community leaders and residents in Dolphin House and Park, located just off the South Circular Road in Dublin’s South Inner City, have had enough of broken promises, politicians saying money is no problem, and ministers saying planning could be fast-tracked.', 'https://changingireland.ie/wp-content/uploads/2024/06/IMG_9130-scaled.jpeg', '', '[{"slug":"development-work","title":"Development Work"}]', '[{"slug":"barnardos","title":"Barnardos"},{"slug":"community","title":"Community"},{"slug":"community-development","title":"community development"},{"slug":"dolphin-house","title":"Dolphin House"},{"slug":"dolphin-house-community-development-association","title":"Dolphin House Community Development Association"},{"slug":"dolphin-house-regeneration-board","title":"Dolphin House Regeneration Board"},{"slug":"dolphins-barn","title":"Dolphin''s Barn"},{"slug":"dublin","title":"Dublin"},{"slug":"dublin-city-council","title":"Dublin City Council"},{"slug":"dublin-south-city-partnership","title":"Dublin South City Partnership"},{"slug":"fergus-finlay","title":"Fergus Finlay"},{"slug":"human-rights","title":"human rights"},{"slug":"human-rights-act","title":"Human Rights Act"},{"slug":"inner-city","title":"inner city"},{"slug":"irish-human-rights-and-equality-commission","title":"Irish Human Rights and Equality Commission"},{"slug":"regeneration","title":"regeneration"}]', '', 254241, 1, '2024-06-13T12:34:02Z', '2024-06-13T14:59:51Z', '2024-06-13T12:34:02Z')
