INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Collective action working in Donegal through county networks', 'collective-action-working-in-donegal-through-county-networks', '<p>&#8220;They have played a crucial role in strengthening connections, shared learning and mutual support amongst community and voluntary groups across Donegal,&#8221; said CEO Padraic Fingleton.</p>
<figure aria-describedby="caption-attachment-254095"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2024/03/Padraic-Fingleton-CEO-DRCD.jpg" alt="" width="1343" height="1584" srcset="https://changingireland.ie/wp-content/uploads/2024/03/Padraic-Fingleton-CEO-DRCD.jpg 1343w, https://changingireland.ie/wp-content/uploads/2024/03/Padraic-Fingleton-CEO-DRCD-254x300.jpg 254w, https://changingireland.ie/wp-content/uploads/2024/03/Padraic-Fingleton-CEO-DRCD-868x1024.jpg 868w, https://changingireland.ie/wp-content/uploads/2024/03/Padraic-Fingleton-CEO-DRCD-768x906.jpg 768w, https://changingireland.ie/wp-content/uploads/2024/03/Padraic-Fingleton-CEO-DRCD-1302x1536.jpg 1302w, https://changingireland.ie/wp-content/uploads/2024/03/Padraic-Fingleton-CEO-DRCD-1080x1274.jpg 1080w" sizes="(max-width: 1343px) 100vw, 1343px" /><figcaption><em>• Padraic Fingleton, CEO, DRCD. Photo by AM.<br /></em></figcaption></figure>
<p>They include the Donegal Food Response Network, the Donegal Network of Men’s Sheds, the Day Care Centres Network and the Social Enterprise Network Donegal (SEND).</p>
<p>The Donegal Food Response Network engages in crucial work, and by working together the network has more power than groups working in silos.</p>
<p>The Men&#8217;s Sheds Network holds monthly meetings and events such as welding and horticulture demonstrations, a countywide summer engagement event, and a regional Irish Men Sheds Network gathering,</p>
<p>The Donegal Day Care Centre Network allocates resources in terms of staff and funding to address the needs of volunteer committee members in these centres.</p>
<p>The Social Enterprise Network Donegal (SEND) has a membership of 59 social enterprises and it serves as a platform for knowledge sharing and collaboration.</p>
<p>DLDC is also developing support hubs – physical space with additional supports &#8211; for emerging social entrepreneurs as they grow into independent social enterprises.</p>
<p>The Social Enterprise Incubator Hub model offers workshops, one-to-one mentoring, desk space and general office support. DLDC has collaborated with educational partners to deliver the mentoring in marketing, HR and finance.</p>
<p>The aim is to work with anyone with an idea through to operating as a fully-fledged social enterprise. Timeframes will be tailored to the specific social enterprise, typically spanning 12 to 18 months.</p>
<p>The first Social Enterprise Incubator Hub began operating in January and it will be replicated in May and September.</p>', 'Donegal Local Development Company (DLDC) has established a number of networks to support community initiatives.', 'https://changingireland.ie/wp-content/uploads/2024/03/263762647_3456430127814964_4010343819527213303_n-e1710847655139.jpg', '', '[{"slug":"community","title":"Community"}]', '[{"slug":"changingdonegal","title":"#ChangingDonegal"},{"slug":"community-and-voluntary-groups","title":"community and voluntary groups"},{"slug":"community-development","title":"community development"},{"slug":"donegal","title":"Donegal"},{"slug":"donegal-food-response-network","title":"Donegal Food Response Network"},{"slug":"donegal-local-development-company-dldc","title":"Donegal Local Development Company DLDC"},{"slug":"local-development-company","title":"local development company"},{"slug":"mens-sheds","title":"Men''s Sheds"},{"slug":"rural-development","title":"rural development"},{"slug":"social-enterprise","title":"social enterprise"},{"slug":"social-enterprise-incubator-hub","title":"Social Enterprise Incubator Hub"},{"slug":"social-enterprise-network-donegal-send","title":"Social Enterprise Network Donegal (SEND)"},{"slug":"the-day-care-centres-network","title":"the Day Care Centres Network"},{"slug":"the-donegal-network-of-mens-sheds","title":"the Donegal Network of Men’s Sheds"}]', '', 253863, 1, '2024-06-06T09:08:01Z', '2024-06-04T12:08:50Z', '2024-06-06T09:08:01Z')
