INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€16 million investment in Ireland’s great outdoors', 'e16-million-investment-in-irelands-great-outdoors', '<p><span>Greenways, Blueways, forest parks and cycling facilities across the country will receive funding as the Government pledges to focus on outdoor adventure tourism as the summer season approaches. </span></p>
<p><span>It will also assist with the establishment of new walking trails, as well as access points for kayaking, paddle-boarding, swimming and other water based activities</span></p>
<p><span>Minister for Rural and Community Development, Heather Humphreys said: &#8220;Our beautiful outdoors have never been more available to us than today. With the summer months upon us, now is the time to enjoy the wonderful amenities right on our doorstep.&#8221;</span></p>
<p><span>Among the projects being funded today include:</span></p>
<ul>
<li><span>       Belmullet Tidal Pool, Co Mayo: €295,974</span></li>
<li><span>       Boyne Valley to Lakelands Greenway Enhancement, Co Meath: €200,000</span></li>
<li><span>       Ardmore Beach Walkway, Co Waterford: €500,000</span></li>
<li><span>       Durrus Coastal Walkway, Co Cork: €200,000</span></li>
<li><span>       Lough Boora Discovery Park, Co Offaly: €500,000</span></li>
<li><span>       Cliffs of Moher Coastal Walk, Co Clare: €500,000</span></li>
<li><span>       Castlecomer Discovery Park Bike Trail – Co. Kilkenny: €500,000</span></li>
<li><span>      The Ryder Cup Way – Co Limerick: €399,983</span></li>
</ul>
<p><span>&#8220;The times of lock downs are thankfully behind us but those times gave us all an appreciation of what our stunning outdoors had to offer us for our mental and physical wellbeing.</span></p>
<p><span>&#8220;Our world class outdoor amenities continue to make rural Ireland the place to be for adventure tourists as well as those who appreciate a more sedate pace of life. These projects are spread throughout the country, so everyone can avail of the outdoors,” added Minister Humphreys. </span></p>
<p><span>Details of all projects are available </span><a href="https://www.gov.ie/pdf/?file=https://assets.gov.ie/295147/45fc2f03-346e-4fed-85d2-4a6abc4f1b69.pdf#page=null"><span>here</span></a><span>.</span></p>', 'A total of 69 projects nationwide will benefit from a €16 million funding investment in outdoor recreation projects.', 'https://changingireland.ie/wp-content/uploads/2024/06/bw2-633-scaled.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"blueway","title":"blueway"},{"slug":"castlecomer-discovery-park","title":"Castlecomer Discovery Park"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"funding","title":"funding"},{"slug":"greenway","title":"Greenway"},{"slug":"lough-boora-discovery-park","title":"Lough Boora Discovery Park"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"our-rural-future","title":"Our Rural Future"},{"slug":"outdoor-recreation","title":"outdoor recreation"},{"slug":"outdoor-recreation-infrastructure-scheme","title":"Outdoor Recreation Infrastructure Scheme"},{"slug":"ryder-cup","title":"Ryder Cup"}]', '', 254237, 1, '2024-06-04T11:52:10Z', '2024-06-04T11:52:10Z', '2024-06-04T11:52:10Z')
