INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New bursary launched to support rural development students', 'new-bursary-launched-to-support-rural-development-students', '<p><span>Minister for Rural and Community Development, Heather Humphreys has launched a new bursary to support a number of Masters students in the area of rural development.</span></p>
<p><span>As part of the initiative, six students will be supported with a bursary with a value of €60,000.</span></p>
<p><span>The initiative is being rolled out in partnership with Irish third level colleges and delivers upon a commitment in the five-year rural development policy, Our Rural Future.</span></p>
<p><span>The bursary was developed in collaboration with the Higher Education Institution Network, which was established by the Department to encourage the wider take-up of rural development research at postgraduate level. </span></p>
<p><span>Minister Humphreys said: &#8220;We hope that this financial support will encourage and support graduates who want to continue their studies and pursue a future career in the area of rural development. </span></p>
<p><span>&#8220;We hope to see applications from candidates in all disciplines relevant to sustainable rural development outlined in Our Rural Future.</span></p>
<p><span>&#8220;We welcome research projects that will contribute to the evidence basis which will underpin government policies relevant to sustainable rural development and help us address the challenges and seize the opportunities ahead of us.&#8221;</span></p>
<p><span>Expressions of Interest were invited from the Network in order to enhance collaboration between higher education institutions, research organisations and Government.</span></p>
<p><span>Funding is now being awarded to a joint proposal by University College Dublin, University of Galway and University College Cork for their complementary Masters programmes in rural development with specialisms in rural innovation, climate adaptation, and sustainable development.  </span></p>
<p><span>The bursary will be funded by the DRCD and administered by University College Dublin as the lead partner organisation. </span></p>
<p><span>It will support six students to undertake a Masters programme in rural development, two students in each of the three partnering universities.</span></p>
<p><span>The students, who will be selected by the universities, will engage with the Department and other nominated departments in the formulation of specific research questions focused on advancing the objectives of Our Rural Future and providing an evidence base to aid the development of public policy or support evaluation of specific policy challenges. </span></p>', '€60,000 bursary will support six Masters students at University College Dublin, University of Galway, and University College Cork.', 'https://changingireland.ie/wp-content/uploads/2024/05/classroom-1699745_1280.jpg', '', '[{"slug":"grants-subsidies","title":"Grants & Subsidies"}]', '[{"slug":"bursary","title":"bursary"},{"slug":"community-development","title":"community development"},{"slug":"department-rural-community-development-drcd","title":"Department of Rural and Community Development"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"our-rural-future","title":"Our Rural Future"},{"slug":"rural-development","title":"rural development"},{"slug":"third-level-education","title":"third level education"},{"slug":"university-college-cork","title":"University College Cork"},{"slug":"university-college-dublin","title":"University College Dublin"},{"slug":"university-of-galway","title":"University of Galway"}]', '', 254232, 1, '2024-05-28T09:22:41Z', '2024-05-27T11:55:31Z', '2024-05-28T09:22:41Z')
