INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Community worker sees unmet needs and untapped potential', 'community-worker-sees-unmet-needs-and-untapped-potential', '<p>With rural transport in remote areas still &#8220;terrible&#8221;, the driving test is a challenge for non-English or Irish speakers and third level choices perplexing. If they received more help on these and other issues, it would help them to integrate and be of wider benefit to society and to the economy.</p>
<p>She said, “Apart from the energy they bring and their different viewpoints on the world, the Ukrainians who’ve come here to Arranmore are very skilled – in communications, engineering, graphic design.</p>
<p>“I don’t think the government recognises the huge potential they have in Ukrainians who want to give back to the community. They would raise the standards of things in Ireland.</p>
<p>“A lot of the young people doing the Leaving Cert now are also doing their Ukrainian exams because they don’t know if they are going to stay in Ireland or return to Ukraine. I think they need a lot more support before they make their university choices. That whole age group needs to be better looked after,&#8221; Fiona added.</p>
<p>&#8220;The Government and people like me need to do more because Ukrainians need better access to information and advice,&#8221; she concluded.</p>', 'Active Arranmore coordinator Fiona Ní Ghloinn believes the Government could be doing more to help Ukrainians in their late teens and twenties to integrate.', 'https://changingireland.ie/wp-content/uploads/2024/03/Fiona.png', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[{"slug":"changingdonegal","title":"#ChangingDonegal"},{"slug":"active-arranmore","title":"Active Arranmore"},{"slug":"arranmore-island","title":"Arranmore Island"},{"slug":"community-development","title":"community development"},{"slug":"donegal","title":"Donegal"},{"slug":"education","title":"education"},{"slug":"integration","title":"integration"},{"slug":"leaving-certificate","title":"Leaving certificate"},{"slug":"refugee-supports","title":"refugee supports"},{"slug":"refugees","title":"refugees"},{"slug":"rural-development","title":"rural development"},{"slug":"transport","title":"transport"},{"slug":"ukrainian-refugees","title":"Ukrainian refugees"},{"slug":"ukrainians","title":"Ukrainians"}]', '', 253862, 1, '2024-05-24T09:40:04Z', '2024-05-24T09:39:11Z', '2024-05-24T09:40:04Z')
