INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Record €164 million funding for rural towns and villages', 'record-e164-million-funding-for-rural-towns-and-villages', '<p><span>The largest allocation to date under the Rural Regeneration and Development Fund places a particular emphasis on the revitalisation of rural town centres,</span><span> combating vacancy and dereliction.</span></p>
<p><span>Announcing the funding at Loophead Lighthouse in Clare this morning, Minister Humphreys said: </span><span>&#8220;</span><span>Today I am announcing an unprecedented €164 million in funding for 30 landmark projects in rural Ireland. This announcement has been made possible by the Rural Regeneration and Development Fund, which is providing strategic capital funding for significant projects around the country. </span></p>
<p><span>&#8220;The funding announced today will revitalise towns and villages in line with the Town Centre First Policy, addressing vacancy and dereliction, stimulating rural economies and responding to community needs&#8221;. </span></p>
<p><span>The successful projects announced today include:</span></p>
<ul>
<li aria-level="1"><span>Ballyhaunis, Co Mayo (€5.2 million): Redevelopment of a derelict convent primary school building and grounds to provide a public library, enterprise hub and public park.</span></li>
<li aria-level="1"><span>Limerick Greenway Hubs Development Project, Co Limerick (€9.6 million): Redevelopment of former station houses along the Limerick Greenway route to create mini destinations, trailheads and service hubs.</span></li>
<li aria-level="1"><span>Cresslough, Co Donegal (€12.1 million): The creation of a new central hub that will be transformative for the community.</span></li>
<li aria-level="1"><span>Cahersiveen, Co Kerry (€6.4 million): Regeneration of the town centre including the renovation of an historic building as a community facility and development of a waterfront amenity and boardwalk.</span></li>
<li aria-level="1"><span>Enniscrone, Co Sligo (€8.4 million):  Regeneration of key seafront areas including the redevelopment of the historic Cliff Bath House, upgrading of the Cliff Walk and redevelopment of a derelict building to provide a new community pavilion.</span></li>
<li aria-level="1"><span>Baile Bhúirne, Co Cork (€3.2 million): Redevelopment of a former residential school to provide a Regional Development Centre – an enterprise development, training and research facility.</span></li>
</ul>
<p><span>The Minister added: &#8220;</span><span>Today, I have announced the largest allocation of funding since the RRDF was established. The RRDF alone has now invested over €577 million in funding for projects in rural Ireland.</span></p>
<p><span>&#8220;This is a truly transformative level of funding that will make a real and lasting difference in rural communities throughout Ireland.&#8221;</span></p>
<p><span>Full details of the successful projects can be found </span><a href="https://www.gov.ie/en/publication/7be140-test/#fifth-call-under-the-fund"><span>here</span></a><span>.</span></p>
<p>&nbsp;</p>', 'A record €164 million funding allocation has been announced for 30 rural regeneration projects around the country, including the redevelopment of a former convent, and the provision of new community hubs and seaside boardwalks.', 'https://changingireland.ie/wp-content/uploads/2024/05/loop-head.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"co-clare","title":"Co Clare"},{"slug":"community-development","title":"community development"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"funding","title":"funding"},{"slug":"government-funding","title":"government funding"},{"slug":"loop-head-lighthouse","title":"Loop Head Lighthouse"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"our-rural-future","title":"Our Rural Future"},{"slug":"regeneration","title":"regeneration"},{"slug":"rural-development","title":"rural development"},{"slug":"rural-regeneration-and-development-fund","title":"Rural Regeneration and Development Fund"},{"slug":"town-centre-first","title":"Town Centre First"}]', '', 254222, 1, '2024-05-13T11:17:03Z', '2024-05-13T11:37:45Z', '2024-05-13T11:17:03Z')
