INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€25 million boost for library services', 'e25-million-boost-for-library-services', '<p><span>A major investment of more than €25 million for public library services across the country was announced this week.</span></p>
<p><span>Among the projects to be funded are 11 new public libraries and 12 new mobile library vehicles. </span></p>
<p><span>Minister for Rural and Community Development, Heather Humphreys made the announcement this week while opening the country’s newest library, the Mayfair Library in Kilkenny City.</span></p>
<p><span>Funded by the Department of Rural and Community Development and Kilkenny County Council, the development saw an old ballroom transformed into a state-of-the-art library and community facility at a cost of </span><span>€7.2 million. </span></p>
<p><span>Projects that will be funded include: </span></p>
<ul>
<li aria-level="1"><span>Drogheda Library, Co Louth &#8211; €3 million: The Dominican Church and Priory along the riverfront will be turned into a state-of-the-art community library.</span></li>
<li aria-level="1"><span>   Fingal Library, Co Dublin &#8211; €3 million: A new flagship library in the Cultural Centre of Fingal. The project will also include a 163-seat theatre, a gallery, café, a tourist information bureau and office space.</span></li>
<li aria-level="1"><span>Ballymote Library, Co Sligo &#8211;  €1.31 million: This project will see a 75-year-old former cinema building transformed into a library and community facility.</span></li>
<li aria-level="1"><span>Ballywaltrim Library, Co Wicklow &#8211; €3 million: A new state-of-the-art two-storey building in Bray, featuring a space for teenagers, public access PCs, study and remote working desks and work from home hubs.</span></li>
<li aria-level="1"><span>Ballybay Library, Co Monaghan &#8211; €1.25 million: The refurbishment of the Market House on the main street into a modern public community library facility.</span></li>
<li aria-level="1"><span>Clane Library, Co Kildare – €1.9 million: Kildare County Council has purchased a former childcare facility and retail outlet for the purpose of providing a new library facility in Clane.</span></li>
</ul>
<p><span>Almost €2.7 million in funding has been earmarked for new mobile library vehicles.</span></p>
<p><span>These will be rolled out in Clare, Galway, Kerry, Kildare, Kilkenny, Limerick, Louth, Roscommon, Sligo, Waterford and Wexford.</span></p>
<p><span>Minister Humphreys commented: &#8220;This will see the delivery of 11 new and extended library facilities across the country, in places such as Drogheda, Bray, New Ross, Swords, Ballymote and Clonmel. The projects include old churches and priories, cinemas and market-houses which will be transformed for 21st century use. </span></p>
<p><span>&#8220;This goes to the heart of what we are working to achieve under our five-year rural development strategy, &#8216;Our Rural Future&#8217;.</span></p>
<p><span>&#8220;As part of this announcement, there will also be an investment of almost €2.7 million in our mobile library vehicles, which have proven extremely popular in towns and villages across the country.”</span></p>
<p><span>  </span></p>
<p><span> </span></p>', 'Projects will include the transformation of an old church in Co Louth, and a former cinema in Co Sligo into new state-of-the-art public libraries and community facilities', 'https://changingireland.ie/wp-content/uploads/2024/04/mayfair-library-kilkenny2.jpg', '', '[{"slug":"funding-programmes","title":"Funding Programmes"}]', '[{"slug":"clare","title":"Clare"},{"slug":"department-of-rural-and-community-development-drcd","title":"Department of Rural and Community Development (DRCD)"},{"slug":"fingal","title":"Fingal"},{"slug":"funding","title":"funding"},{"slug":"galway","title":"Galway"},{"slug":"kerry","title":"Kerry"},{"slug":"kildare","title":"Kildare"},{"slug":"kilkenny","title":"Kilkenny"},{"slug":"library-service","title":"Library Service"},{"slug":"limerick","title":"Limerick"},{"slug":"louth","title":"Louth"},{"slug":"minister-heather-humphreys","title":"Minister Heather Humphreys"},{"slug":"monaghan","title":"Monaghan"},{"slug":"our-rural-future","title":"Our Rural Future"},{"slug":"public-libraries","title":"public libraries"},{"slug":"roscommon","title":"Roscommon"},{"slug":"sligo","title":"Sligo"},{"slug":"tipperary","title":"Tipperary"},{"slug":"waterford","title":"Waterford"},{"slug":"wexford","title":"Wexford"},{"slug":"wicklow","title":"Wicklow"}]', '', 254204, 1, '2024-04-26T09:05:16Z', '2024-04-25T11:28:26Z', '2024-04-26T09:05:16Z')
